'use client';

interface Participant {
  id: string;
  name: string;
}

interface ParticipantsProps {
  participants: Participant[];
  currentClientId?: string;
  connected: boolean;
  roomId: string;
}

// Color palette for participant avatars — generated by participant index
const AVATAR_COLORS = [
  'bg-blue-500', 'bg-green-500', 'bg-purple-500', 'bg-orange-500',
  'bg-pink-500', 'bg-teal-500', 'bg-red-500', 'bg-indigo-500',
];

export default function Participants({ participants, currentClientId, connected, roomId }: ParticipantsProps) {
  return (
    <div className="flex items-center gap-3 px-4 py-2 bg-white border-b border-gray-100">
      {/* Connection status badge */}
      <div className="flex items-center gap-1.5">
        <div className={`w-2 h-2 rounded-full ${connected ? 'bg-green-500' : 'bg-red-400'}`} />
        <span className="text-xs text-gray-500">
          {connected ? `Room: ${roomId}` : 'Disconnected'}
        </span>
      </div>

      <div className="w-px h-4 bg-gray-200" />

      {/* Participant avatar stack */}
      <div className="flex items-center -space-x-1">
        {participants.map((p, i) => (
          <div
            key={p.id}
            title={p.id === currentClientId ? `${p.name} (You)` : p.name}
            className={`w-7 h-7 rounded-full ${AVATAR_COLORS[i % AVATAR_COLORS.length]} 
              border-2 border-white flex items-center justify-center text-white text-xs font-bold
              cursor-default select-none`}
          >
            {p.name.charAt(0).toUpperCase()}
          </div>
        ))}
      </div>

      <span className="text-xs text-gray-400">
        {participants.length} user{participants.length !== 1 ? 's' : ''} online
      </span>
    </div>
  );
}
